import math

def estimate_cost(notional, adv, spread_bps, sigma, c):
    """Pre-trade cost of one order, in pounds:
    half the spread plus square-root impact."""
    half_spread = spread_bps / 2 / 10000
    impact = c * sigma * math.sqrt(notional / adv)
    return notional * (half_spread + impact)

def days_to_exit(position, adv, participation):
    """Trading days to exit at a share of daily volume."""
    return position / (participation * adv)
